/**
 * Body of POST /reservations. A player books for themselves; the admin fields book
 * on behalf of a member (userId + paymentMethod) or a phone / walk-in guest (guestName).
 */
export interface ReservationInput {
  terrainId: number;
  startTime: string;
  /** full_court (default): the booker pays every spot · own_spot: one spot, the rest stays open */
  bookingMode?: "full_court" | "own_spot";
  /** own_spot only: list the match in the open matches */
  isPublic?: boolean;
  publicDescription?: string;
  equipment?: { itemId: number; quantity: number }[];
  notes?: string;
  /** Admin: the member the booking is for */
  userId?: number;
  /** Admin: how that member pays (default token) */
  paymentMethod?: "token" | "cash_club";
  /** Admin: guest without an account */
  guestName?: string;
  guestPhone?: string;
  bookingType?: ReservationInputBookingType;
}

